/* Operation Tankity: the solo rules.
 *
 * The rules of a match against the drone battery, without a page: dealing,
 * mustering a round, the turn order, settling a volley, 1-ups, a drone's
 * aim and what a purchase does. match.ts plays them with words and sound. Nothing here reads a clock
 * or Math.random, so the same seed deals the same match anywhere. */
import { aiChoose, pickTactic } from './ai.ts';
import type { AimChoice } from './ai.ts';
import { carryArmor, maxArmor } from './armor.ts';
import { ONE_SHOT, buyPacks, isOneShot, soloBuy } from './buy.ts';
export { ONE_SHOT, buyPacks, isOneShot, soloBuy };
export type { BuyResult } from './buy.ts';
import { SOLO_STEP, WATCH_TURNS } from './flow.ts';
import { dealDrone, droneVisit, personalityOf } from './drones.ts';
import type { Drone } from './drones.ts';
import { TUNE, clamp, fieldWidthOk, gauss, genTerrain, hashSeed, mulberry32, restY, spawnSpots, startAmmo, surfY } from './sim.ts';
import type { Arsenal, Cloud, Difficulty, Hills, ShopRow, Tank, World } from './sim.ts';
import { wallsFor } from './walls.ts';
import type { WallsSetting } from './walls.ts';

export { SOLO_STEP };
export const FOES = [
  { id: 'reaper', color: '#ff0000' },
  { id: 'wraith', color: '#00ffff' },
  { id: 'spotter', color: '#ff00ff' },
] as const;

export interface SoloTank extends Tank { maxHp: number; color?: string; body?: string; personality?: string }
export interface SoloState extends World {
  seed: string;
  /** How well the drones aim this match (ai.ts DIFFICULTY); set at the deal, never during play. */
  difficulty: Difficulty;
  /** The field's width, dealt once per match from the screen (spec 6.6). */
  w: number;
  hills: Hills | null;
  body: string;
  clouds: Cloud[];
  tanks: SoloTank[];
  turn: number;
  firstTurn: number;
  lives: number;
  nextOneUp: number;
  roundsWon: number;
  tactics: Record<string, string>;
  watchTurns: number;
  armor: number;
  plate: number;
  fuelBank: number;
  /** The player's parachutes: they stack, and one opens on a hard fall. */
  chutes: number;
  /** The drones' money, one per foe in FOES' order: their personality, cash, ammo, armor and gear. */
  drones: Drone[];
}

/** A new match at a difficulty and a width: the stake, three lives, full armor, and the pre-match hills (drawn, never fought on). */
export function soloDeal(G: SoloState, arsenal: Arsenal, seed: string, difficulty: Difficulty, w: number): void {
  if (!fieldWidthOk(w)) throw new RangeError(`field width ${w}`);
  G.w = w;
  G.seed = seed;
  G.difficulty = difficulty;
  G.rng = mulberry32(hashSeed(seed));
  G.lives = TUNE.lives;
  G.score = 0;
  G.cash = 600;
  G.nextOneUp = TUNE.oneUpEvery;
  G.roundsWon = 0;
  G.round = 0;
  G.tactics = {};
  G.firstTurn = 0;
  G.ammo = startAmmo(arsenal);
  for (const k of arsenal.order) if (!(k in G.ammo)) G.ammo[k] = 0;
  G.selected = 'shell';
  G.fuelBank = 0;
  G.armor = TUNE.playerArmor;
  G.plate = 0;
  G.shield = false;
  G.jammer = 0;
  G.bunker = 0;
  G.laststand = false;
  G.chutes = 0;
  G.watchTurns = 0;
  const g = genTerrain(G.rng, G.w);
  G.terrain = g.terrain;
  G.clouds = g.clouds;
  G.hills = g.hills;
  G.tanks = [];
  G.shells = [];
  // The drones start as a player does, a personality each, and shop before the first round
  // (their draws come from the seed, never G.rng).
  G.drones = FOES.map((_, i) => dealDrone(arsenal, seed, i + 1));
  G.drones.forEach((d, i) => droneVisit(d, arsenal, seed, 0, i + 1));
}

/** A round's hills, wind and four units, spread anywhere; the opener rotates round by round; and its
 *  walls, the pick or Random's draw (made last, so no other pick moves the match's stream). */
export function soloMuster(G: SoloState, arsenal: Arsenal, walls: WallsSetting = 'none'): void {
  const g = genTerrain(G.rng, G.w);
  G.terrain = g.terrain;
  G.clouds = g.clouds;
  G.hills = g.hills;
  G.watchTurns = 0;
  G.wind = Math.round((G.rng() * 2 - 1) * 8);
  const order = spawnSpots(1 + FOES.length, G.rng, G.w); // over the whole field: the extra hills are part of the fight
  const fuel = TUNE.fuel + (G.fuelBank || 0);
  G.fuelBank = 0;
  G.tanks = [{
    id: 'tank', isPlayer: true, color: '#ffff00', body: G.body,
    x: order[0]!, y: 0, angle: 62, power: 55, hp: G.armor, maxHp: maxArmor(G.plate), fuel,
  }];
  FOES.forEach((f, i) => {
    // A drone musters with what it carries: the armor, shells, parachutes, shield and cash its
    // shopping and its rounds left it, as a player does.
    const d = G.drones[i]!;
    G.tanks.push({
      id: f.id, isPlayer: false, color: f.color,
      x: order[i + 1]!, y: 0, angle: 62, power: 55, hp: d.armor, maxHp: maxArmor(d.plate), fuel: 0,
      ammo: { ...d.ammo }, chutes: d.chutes, shield: d.shield, cash: d.cash,
      personality: personalityOf(arsenal, d.personality)?.name,
      s: G.tactics[f.id] || (G.tactics[f.id] = pickTactic(G.rng)),
    });
  });
  for (const t of G.tanks) {
    t.y = surfY(G.terrain, t.x);
    t.dirS = t.x < G.w / 2 ? 1 : -1; // face the middle of the field
  }
  G.turn = G.firstTurn % G.tanks.length;
  G.firstTurn++;
  G.shells = [];
  G.walls = wallsFor(walls, G.rng);
}

/** Standing tanks sit exactly where they rest (the ground, or a unit they
 *  stand on) and are drawn there once the falls are over, so a settled round
 *  starts from exact heights. The falls' armor was decided by the volley's
 *  settle (sim.ts settleVolley); this only places units. */
export function snapTanks(G: Pick<SoloState, 'tanks' | 'terrain'>): void {
  for (const t of G.tanks) {
    if (t.hp <= 0) continue;
    t.y = restY(G.tanks, G.terrain, t);
    t.drawY = undefined;
    t.vy = 0;
    t.chute = t.chuteArmed = t.chuteOpen = false;
  }
}

export function soloNextTurn(G: SoloState): void {
  const n = G.tanks.length;
  for (let k = 1; k <= n; k++) {
    if (G.tanks[(G.turn + k) % n]!.hp > 0) { G.turn = (G.turn + k) % n; return; }
  }
}

export type Settled =
  | { kind: 'next' }
  | { kind: 'roundWon'; bonus: number; prize: number }
  | { kind: 'tankLost' }
  | { kind: 'matchLost' };

/** A round's end for the drones: what each held, spent and earned goes back to its record, its armor carries as a
 *  player's does (a wreck re-musters at full), and each shops before the next round, by the player's buy rules. */
function settleDrones(G: SoloState, arsenal: Arsenal): void {
  FOES.forEach((f, i) => {
    const t = G.tanks.find(x => x.id === f.id);
    const d = G.drones[i]!;
    if (t) {
      d.cash = t.cash || 0;
      d.ammo = t.ammo || d.ammo;
      d.chutes = t.chutes || 0;
      d.shield = !!t.shield;
      d.armor = carryArmor({ armor: d.armor, plates: d.plate }, t.hp, t.hp <= 0).armor;
    }
    droneVisit(d, arsenal, G.seed, G.round, i + 1);
  });
}

/** After a volley: play on (the wind shifts, the next unit is up), or the round ends. */
export function soloSettle(G: SoloState, arsenal: Arsenal): Settled {
  snapTanks(G);
  const me = G.tanks[0]!;
  const alive = G.tanks.filter(t => t.hp > 0).length;
  // A round ends with one unit left; with the player wrecked the drones fight
  // on for at most WATCH_TURNS settles, so a stalemate cannot run forever.
  if (alive > 1 && !(me.hp <= 0 && ++G.watchTurns >= WATCH_TURNS)) {
    G.wind = clamp(Math.round(G.wind + gauss(G.rng) * 2), -12, 12);
    soloNextTurn(G);
    return { kind: 'next' };
  }
  const prize = TUNE.roundWinCash + G.round * 100;
  // The round's sole survivor takes the prize, a drone as a player does.
  const sole = alive === 1 ? G.tanks.find(t => t.hp > 0)! : null;
  if (sole && !sole.isPlayer) sole.cash = (sole.cash || 0) + prize;
  settleDrones(G, arsenal);
  if (me.hp <= 0) {
    G.lives -= 1;
    G.armor = carryArmor({ armor: G.armor, plates: G.plate }, 0, true).armor;
    if (G.lives <= 0) { G.lives = 0; return { kind: 'matchLost' }; }
    return { kind: 'tankLost' };
  }
  G.roundsWon += 1;
  const bonus = TUNE.roundWinScore + G.round * 150;
  G.score += bonus;
  G.cash += prize;
  // Trick timers tick down on claimed rounds, not on wrecked restarts.
  if (G.jammer > 0) G.jammer--;
  if (G.bunker > 0) G.bunker--;
  G.armor = carryArmor({ armor: G.armor, plates: G.plate }, me.hp, false).armor;
  return { kind: 'roundWon', bonus, prize };
}

export type OneUp = { kind: 'life' | 'points'; lives: number };
/** Every 3000 points a life, up to five; past five, 500 points instead. */
export function soloOneUps(G: SoloState): OneUp[] {
  const out: OneUp[] = [];
  while (G.score >= G.nextOneUp) {
    G.nextOneUp += TUNE.oneUpEvery;
    if (G.lives < TUNE.maxLives) { G.lives += 1; out.push({ kind: 'life', lives: G.lives }); }
    else { G.score += 500; out.push({ kind: 'points', lives: G.lives }); }
  }
  return out;
}

/** A drone's choice for its turn, aimed at the match's difficulty (aiChoose reads
 *  G.difficulty); a strategy switch is remembered for later rounds. */
export function soloAim(G: SoloState, arsenal: Arsenal, t: SoloTank): AimChoice {
  const plan = aiChoose(G, arsenal, t);
  if (plan.tactic) G.tactics[t.id] = plan.tactic;
  return plan;
}
